#!/usr/bin/env node
import fs from 'node:fs';
import path from 'node:path';
import zlib from 'node:zlib';

const root = process.cwd();
const stamp = new Date().toISOString().replace(/[:.]/g, '-');
const payload = '';
const files = JSON.parse(zlib.gunzipSync(Buffer.from(payload, 'base64')).toString('utf8'));

function backupIfExists(relativePath) {
  const target = path.join(root, relativePath);
  if (!fs.existsSync(target)) return;
  const backup = path.join(root, relativePath + `.before-authored-book1-${stamp}`);
  fs.copyFileSync(target, backup);
  console.log(`Backed up ${relativePath} -> ${path.relative(root, backup)}`);
}

backupIfExists('src/slides.js');
backupIfExists('lectures/manifest.json');

for (const [relativePath, content] of Object.entries(files)) {
  const target = path.join(root, relativePath);
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, content.endsWith('\n') ? content : content + '\n');
}

const manifest = JSON.parse(files['lectures/manifest.json']);
const deckCount = manifest.length;
const slideCount = manifest.reduce((total, entry) => {
  const deck = JSON.parse(files[entry.path]);
  return total + deck.slides.length;
}, 0);
console.log(`Installed authored Book I Slides: ${deckCount} decks, ${slideCount} slides.`);
console.log('Next: run node scripts/build-slides.mjs, then npm start.');
